from typing import List

class Solution:
    def findAndReplacePattern(self, words: List[str], pattern: str) -> List[str]:
        def match(w: str) -> bool:
            m1, m2 = {}, {}
            for c1, c2 in zip(w, pattern):
                if m1.setdefault(c1, c2) != c2 or m2.setdefault(c2, c1) != c1:
                    return False
            return True

        return [w for w in words if match(w)]

class Solution {
public:
    bool match(string& w, string& p) {
        unordered_map<char, char> m1, m2;
        for (size_t i = 0; i < w.length(); i++) {
            char c1 = w[i], c2 = p[i];
            if (m1.count(c1) && m1[c1] != c2) return false;
            if (m2.count(c2) && m2[c2] != c1) return false;
            m1[c1] = c2;
            m2[c2] = c1;
        }
        return true;
    }

    vector<string> findAndReplacePattern(vector<string>& words, string pattern) {
        vector<string> ans;
        for (string& w : words) {
            if (match(w, pattern)) ans.push_back(w);
        }
        return ans;
    }
};

class Solution {
    private boolean match(String w, String p) {
        Map<Character, Character> m1 = new HashMap<>();
        Map<Character, Character> m2 = new HashMap<>();
        for (int i = 0; i < w.length(); i++) {
            char c1 = w.charAt(i), c2 = p.charAt(i);
            if (m1.containsKey(c1) && m1.get(c1) != c2) return false;
            if (m2.containsKey(c2) && m2.get(c2) != c1) return false;
            m1.put(c1, c2);
            m2.put(c2, c1);
        }
        return true;
    }

    public List<String> findAndReplacePattern(String[] words, String pattern) {
        List<String> ans = new ArrayList<>();
        for (String w : words) {
            if (match(w, pattern)) ans.add(w);
        }
        return ans;
    }
}

var findAndReplacePattern = function(words, pattern) {
    function match(w) {
        const m1 = new Map(), m2 = new Map();
        for (let i = 0; i < w.length; i++) {
            const c1 = w[i], c2 = pattern[i];
            if (m1.has(c1) && m1.get(c1) !== c2) return false;
            if (m2.has(c2) && m2.get(c2) !== c1) return false;
            m1.set(c1, c2);
            m2.set(c2, c1);
        }
        return true;
    }
    return words.filter(match);
};
